#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    long long maxSubarrays(int n, vector<vector<int>>& conflictingPairs) {
        long long validSubarrays = 0;
        int maxLeft = 0;
        int secondMaxLeft = 0;
        vector<long long> gains(n + 1, 0);
        vector<vector<int>> conflicts(n + 1);

        for (const auto& pair : conflictingPairs) {
            int a = pair[0], b = pair[1];
            conflicts[max(a, b)].push_back(min(a, b));
        }

        for (int right = 1; right <= n; ++right) {
            for (int left : conflicts[right]) {
                if (left > maxLeft) {
                    secondMaxLeft = maxLeft;
                    maxLeft = left;
                } else if (left > secondMaxLeft) {
                    secondMaxLeft = left;
                }
            }
            validSubarrays += right - maxLeft;
            gains[maxLeft] += maxLeft - secondMaxLeft;
        }

        long long maxGain = 0;
        for (int i = 1; i <= n; i++) {
            maxGain = max(maxGain, gains[i]);
        }
        return validSubarrays + maxGain;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    public long maxSubarrays(int n, int[][] conflictingPairs) {
        long validSubarrays = 0;
        int maxLeft = 0;
        int secondMaxLeft = 0;
        long[] gains = new long[n + 1];
        List<Integer>[] conflicts = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) conflicts[i] = new ArrayList<>();

        for (int[] pair : conflictingPairs) {
            int a = pair[0], b = pair[1];
            conflicts[Math.max(a, b)].add(Math.min(a, b));
        }

        for (int right = 1; right <= n; right++) {
            for (int left : conflicts[right]) {
                if (left > maxLeft) {
                    secondMaxLeft = maxLeft;
                    maxLeft = left;
                } else if (left > secondMaxLeft) {
                    secondMaxLeft = left;
                }
            }
            validSubarrays += (right - maxLeft);
            gains[maxLeft] += (maxLeft - secondMaxLeft);
        }

        long maxGain = 0;
        for (int i = 1; i <= n; i++) {
            maxGain = Math.max(maxGain, gains[i]);
        }
        return validSubarrays + maxGain;
    }
}

/**
 * @param {number} n
 * @param {number[][]} conflictingPairs
 * @return {number}
 */
var maxSubarrays = function(n, conflictingPairs) {
    let validSubarrays = 0;
    let maxLeft = 0;
    let secondMaxLeft = 0;
    const gains = new Array(n + 1).fill(0);
    const conflicts = Array.from({ length: n + 1 }, () => []);

    for (const [a, b] of conflictingPairs) {
        conflicts[Math.max(a, b)].push(Math.min(a, b));
    }

    for (let right = 1; right <= n; right++) {
        for (const left of conflicts[right]) {
            if (left > maxLeft) {
                secondMaxLeft = maxLeft;
                maxLeft = left;
            } else if (left > secondMaxLeft) {
                secondMaxLeft = left;
            }
        }
        validSubarrays += right - maxLeft;
        gains[maxLeft] += maxLeft - secondMaxLeft;
    }

    let maxGain = 0;
    for (let i = 1; i <= n; i++) {
        if (gains[i] > maxGain) maxGain = gains[i];
    }
    return validSubarrays + maxGain;
};
